#!/usr/bin/env python3
"""
Fetch USGS streamflow data for Michigan stations for April 1-7, 2025,
get flood thresholds from NWS, and output flood_results.csv.
"""

import urllib.request
import json
import csv
import os
import time
import ssl

# Read station IDs
with open("/root/data/michigan_stations.txt") as f:
    stations = [line.strip() for line in f if line.strip()]

print(f"Total stations: {len(stations)}")

start_date = "2025-04-01"
end_date = "2025-04-07"
station_str = ",".join(stations)
dates_to_check = [f"2025-04-0{d}" for d in range(1, 8)]

# ============================================================
# Step 1: Fetch gage height IV data (instantaneous values)
# ============================================================
print("Fetching instantaneous gage height data...")
url_iv = (
    f"https://waterservices.usgs.gov/nwis/iv/"
    f"?format=json"
    f"&sites={station_str}"
    f"&startDT={start_date}"
    f"&endDT={end_date}"
    f"&parameterCd=00065"
    f"&siteStatus=all"
)

req = urllib.request.Request(url_iv, headers={"User-Agent": "Python/flood-analysis"})
with urllib.request.urlopen(req, timeout=180) as resp:
    iv_data = json.loads(resp.read().decode())

# Get max gage height per station per day
station_daily_max = {}
iv_series = iv_data.get("value", {}).get("timeSeries", [])
print(f"Got {len(iv_series)} IV time series for gage height")

for ts in iv_series:
    site_code = ts["sourceInfo"]["siteCode"][0]["value"]
    if site_code not in station_daily_max:
        station_daily_max[site_code] = {}
    for val in ts["values"][0]["value"]:
        date_str = val["dateTime"][:10]
        val_str = val["value"]
        if val_str and val_str != "":
            try:
                v = float(val_str)
                if v >= 0:
                    if date_str not in station_daily_max[site_code]:
                        station_daily_max[site_code][date_str] = v
                    else:
                        station_daily_max[site_code][date_str] = max(
                            station_daily_max[site_code][date_str], v
                        )
            except ValueError:
                pass

print(f"Parsed gage height for {len(station_daily_max)} stations")

# ============================================================
# Step 2: Get flood stage thresholds
# ============================================================

# Try multiple sources for flood thresholds

flood_thresholds = {}  # {station_id: flood_stage_in_feet}

# Method A: NWS API - get gauges in Michigan
print("\nFetching NWS flood stages...")

# The NWS has flood data keyed by NWS Location ID (e.g., "LNSM4")
# We need to map USGS site numbers to NWS location IDs
# The USGS site service can provide this mapping

# First try: USGS site service with flood stage info
url_site = (
    f"https://waterservices.usgs.gov/nwis/site/"
    f"?format=rdb"
    f"&sites={station_str}"
    f"&siteOutput=expanded"
    f"&siteStatus=all"
)

req_site = urllib.request.Request(url_site, headers={"User-Agent": "Python/flood-analysis"})
with urllib.request.urlopen(req_site, timeout=120) as resp:
    site_text = resp.read().decode()

# Parse RDB format to find relevant columns
lines = site_text.split('\n')
header_line = None
for i, line in enumerate(lines):
    if line.startswith('agency_cd'):
        header_line = i
        break

if header_line is not None:
    headers = lines[header_line].split('\t')
    print(f"Site service columns: {headers[:10]}...")
    # Look for flood-related columns
    flood_cols = [h for h in headers if 'flood' in h.lower()]
    print(f"Flood-related columns: {flood_cols}")

# Method B: Try the USGS waterwatch current floods JSON
print("\nTrying USGS waterwatch current floods...")
# This is a different endpoint that may work
urls_to_try = [
    "https://waterwatch.usgs.gov/webservices/floodstage?format=json",
    "https://waterwatch.usgs.gov/webservices/realtime?format=json&region=mi",
]

for url_try in urls_to_try:
    try:
        req_t = urllib.request.Request(url_try, headers={"User-Agent": "Python/flood-analysis"})
        with urllib.request.urlopen(req_t, timeout=60) as resp:
            data_t = json.loads(resp.read().decode())
        print(f"  Success: {url_try}")
        print(f"  Keys: {list(data_t.keys())[:5]}")
        if "sites" in data_t:
            for site in data_t["sites"]:
                sid = site.get("site_no", "")
                if sid in stations:
                    action = site.get("action_stage", "")
                    flood = site.get("flood_stage", "")
                    threshold = None
                    if action and action != "":
                        try:
                            threshold = float(action)
                        except ValueError:
                            pass
                    if threshold is None and flood and flood != "":
                        try:
                            threshold = float(flood)
                        except ValueError:
                            pass
                    if threshold is not None:
                        flood_thresholds[sid] = threshold
            print(f"  Matched {len(flood_thresholds)} stations so far")
        break
    except Exception as e:
        print(f"  Failed: {url_try} -> {e}")

# Method C: Try NWS API for Michigan gauges
if len(flood_thresholds) < 5:
    print("\nTrying NWS API for Michigan observation stations...")
    # NWS API provides flood stages through their stations endpoint
    nws_url = "https://api.water.noaa.gov/nwps/v1/gauges?state.stateCode=MI"
    try:
        req_nws = urllib.request.Request(nws_url, headers={
            "User-Agent": "Python/flood-analysis",
            "Accept": "application/json"
        })
        with urllib.request.urlopen(req_nws, timeout=120) as resp:
            nws_data = json.loads(resp.read().decode())

        print(f"  NWS response keys: {list(nws_data.keys()) if isinstance(nws_data, dict) else type(nws_data)}")

        # Parse NWS gauge data
        gauges = nws_data if isinstance(nws_data, list) else nws_data.get("gauges", [])
        print(f"  Found {len(gauges)} NWS gauges")

        # Map USGS IDs
        for gauge in gauges:
            usgs_id = gauge.get("usgsSiteId") or gauge.get("usgs_site_id") or gauge.get("usgs_id", "")
            if not usgs_id:
                # Try nested
                if "lid" in gauge:
                    pass  # NWS LID, not USGS
                continue
            usgs_id = str(usgs_id).zfill(8)
            if usgs_id in stations:
                # Look for flood stage
                flood_stage = gauge.get("floodStage") or gauge.get("flood_stage")
                action_stage = gauge.get("actionStage") or gauge.get("action_stage")
                threshold = None
                if action_stage:
                    try:
                        threshold = float(action_stage)
                    except (ValueError, TypeError):
                        pass
                if threshold is None and flood_stage:
                    try:
                        threshold = float(flood_stage)
                    except (ValueError, TypeError):
                        pass
                if threshold is not None:
                    flood_thresholds[usgs_id] = threshold

        print(f"  Matched {len(flood_thresholds)} stations with NWS thresholds")

    except Exception as e:
        print(f"  NWS API failed: {e}")

# Method D: Try individual NWS gauge lookups
if len(flood_thresholds) < 5:
    print("\nTrying NWPS v1 gauges individually...")
    nws_base = "https://api.water.noaa.gov/nwps/v1/gauges"
    try:
        req_all = urllib.request.Request(
            f"{nws_base}?state.stateCode=MI&limit=200",
            headers={"User-Agent": "Python/flood-analysis", "Accept": "application/json"}
        )
        with urllib.request.urlopen(req_all, timeout=120) as resp:
            raw = resp.read().decode()
            nws_all = json.loads(raw)

        if isinstance(nws_all, dict):
            print(f"  Keys: {list(nws_all.keys())}")
            gauges = nws_all.get("gauges", nws_all.get("data", []))
            if not gauges and "features" in nws_all:
                gauges = nws_all["features"]
        else:
            gauges = nws_all

        print(f"  Total gauges: {len(gauges)}")
        if gauges:
            print(f"  Sample gauge keys: {list(gauges[0].keys()) if isinstance(gauges[0], dict) else 'N/A'}")
            # Print first gauge to understand structure
            print(f"  First gauge sample: {json.dumps(gauges[0], indent=2)[:500]}")

        for gauge in gauges:
            # Find USGS site ID in the gauge data
            usgs_id = None
            for key in ["usgsSiteId", "usgs_site_id", "usgsSiteCode", "siteId", "site_id"]:
                if key in gauge:
                    usgs_id = str(gauge[key])
                    break

            if not usgs_id:
                continue

            # Pad to 8 digits
            usgs_id = usgs_id.zfill(8)

            if usgs_id in stations:
                # Find flood thresholds
                threshold = None
                for key in ["actionStage", "action_stage", "floodStage", "flood_stage"]:
                    if key in gauge and gauge[key] is not None:
                        try:
                            threshold = float(gauge[key])
                            break
                        except (ValueError, TypeError):
                            pass

                # Check nested flood categories
                if threshold is None and "floodCategories" in gauge:
                    fc = gauge["floodCategories"]
                    if isinstance(fc, dict):
                        for key in ["actionStage", "action", "floodStage", "minor"]:
                            if key in fc and fc[key] is not None:
                                try:
                                    threshold = float(fc[key])
                                    break
                                except (ValueError, TypeError):
                                    pass

                # Check 'status' or 'thresholds'
                if threshold is None and "status" in gauge:
                    st = gauge["status"]
                    if isinstance(st, dict):
                        for key in ["action_stage", "flood_stage", "actionStage", "floodStage"]:
                            if key in st and st[key] is not None:
                                try:
                                    threshold = float(st[key])
                                    break
                                except (ValueError, TypeError):
                                    pass

                if threshold is not None:
                    flood_thresholds[usgs_id] = threshold
                    print(f"    {usgs_id}: threshold = {threshold}")

        print(f"  Total matched: {len(flood_thresholds)} stations")

    except Exception as e:
        print(f"  NWPS failed: {e}")
        import traceback
        traceback.print_exc()

print(f"\n=== Flood thresholds found for {len(flood_thresholds)} stations ===")
for sid, thresh in sorted(flood_thresholds.items()):
    print(f"  {sid}: {thresh} ft")

# ============================================================
# Step 3: Determine flood days
# ============================================================
print("\n--- Determining flood days ---")

flood_results = {}

for sid in stations:
    if sid in station_daily_max and sid in flood_thresholds:
        threshold = flood_thresholds[sid]
        count = 0
        for d in dates_to_check:
            if d in station_daily_max[sid]:
                if station_daily_max[sid][d] >= threshold:
                    count += 1
        if count > 0:
            flood_results[sid] = count

print(f"Stations with flooding: {len(flood_results)}")
for sid, days in sorted(flood_results.items()):
    t = flood_thresholds.get(sid, "N/A")
    max_gage = max(station_daily_max.get(sid, {}).values()) if sid in station_daily_max else "N/A"
    print(f"  {sid}: {days} flood days (threshold: {t} ft, max gage: {max_gage} ft)")

# ============================================================
# Step 4: Write CSV
# ============================================================
os.makedirs("/root/output", exist_ok=True)
with open("/root/output/flood_results.csv", "w", newline="") as csvfile:
    writer = csv.writer(csvfile)
    writer.writerow(["station_id", "flood_days"])
    for sid, days in sorted(flood_results.items()):
        writer.writerow([sid, days])

print(f"\nResults written to /root/output/flood_results.csv")

